use crate::state::{ActionSequence, AppState, Intent, MacroConfig, StateManager};
use serde::Serialize;
use std::sync::Arc;
use tauri::{command, State};
use uuid::Uuid;

/// WR-05: UUID is generated by the backend and returned to the frontend.
/// The client should NOT supply a UUID — any client-side id is overwritten.
#[command]
pub async fn add_macro(
    state: State<'_, StateManager>,
    config: MacroConfig,
) -> Result<Uuid, String> {
    let (tx, rx) = tokio::sync::oneshot::channel();
    state
        .send_intent(Intent::AddMacro(config, tx))
        .await
        .map_err(|e| e.to_string())?;
    rx.await.map_err(|e| e.to_string())
}

#[command]
pub async fn remove_macro(state: State<'_, StateManager>, id: Uuid) -> Result<(), String> {
    state
        .send_intent(Intent::RemoveMacro(id))
        .await
        .map_err(|e| e.to_string())
}

